                    writer.WriteNull("episode_id");

            if (match.HomeScoreOption.IsSet)
                writer.WriteNumber("home_score", match.HomeScoreOption.Value!.Value);

            if (match.LessonLearnedOption.IsSet)
                if (match.LessonLearnedOption.Value != null)
                    writer.WriteString("lesson_learned", match.LessonLearned);
                else
                    writer.WriteNull("lesson_learned");

            if (match.PossessionPercentageOption.IsSet)
                if (match.PossessionPercentageOption.Value != null)
                    writer.WriteNumber("possession_percentage", match.PossessionPercentageOption.Value!.Value);
                else
                    writer.WriteNull("possession_percentage");

            if (match.ResultOption.IsSet)
            {
                var resultRawValue = MatchResultValueConverter.ToJsonValue(match.Result!.Value);
                writer.WriteString("result", resultRawValue);
            }
            if (match.TedHalftimeSpeechOption.IsSet)
                if (match.TedHalftimeSpeechOption.Value != null)
                    writer.WriteString("ted_halftime_speech", match.TedHalftimeSpeech);
                else
                    writer.WriteNull("ted_halftime_speech");

            if (match.TicketRevenueGbpOption.IsSet)
                if (match.TicketRevenueGbpOption.Value != null)
                    writer.WriteString("ticket_revenue_gbp", match.TicketRevenueGbp);
                else
                    writer.WriteNull("ticket_revenue_gbp");

            if (match.TurningPointsOption.IsSet)
            {
                writer.WritePropertyName("turning_points");
                JsonSerializer.Serialize(writer, match.TurningPoints, jsonSerializerOptions);
            }
            if (match.WeatherTempCelsiusOption.IsSet)
                if (match.WeatherTempCelsiusOption.Value != null)
                    writer.WriteNumber("weather_temp_celsius", match.WeatherTempCelsiusOption.Value!.Value);
                else
                    writer.WriteNull("weather_temp_celsius");
        }
    }
}
